EXPLAIN ANALYZE SELECT dc."id" AS chunk_id, dc."documentId" AS document_id, d."name" AS document_name, d."originalFilename" AS original_filename, dc."chunkIndex" AS chunk_index, dc."content" AS content, (dc."embedding" <=> array_fill(0.1, ARRAY[384])::vector) AS distance FROM "DocumentChunk" dc JOIN "Document" d ON d."id" = dc."documentId" WHERE d."userId" = 1 AND dc."embedding" IS NOT NULL ORDER BY dc."embedding" <=> array_fill(0.1, ARRAY[384])::vector ASC LIMIT 5;
